import { Readable } from "node:stream";
import { createGunzip } from "node:zlib";

import AdmZip from "adm-zip";
import { parseStrictJsonBytes, readRegularFileSnapshot } from "@ultrafuzz/artifacts";
import tar from "tar-stream";

const HANDOFF_PATH = "handoff/current-state.json";
const MAX_JSON_BYTES = 64 * 1024 * 1024;
// adm-zip retains the compressed input, so bound it to the same compatibility
// envelope already used by other report and benchmark bundle readers.
export const MAX_BUNDLE_ARCHIVE_BYTES = 256 * 1024 * 1024;
const MAX_NESTED_ARCHIVE_BYTES = MAX_BUNDLE_ARCHIVE_BYTES;
const MAX_NESTED_UNCOMPRESSED_BYTES = 8 * 1024 * 1024 * 1024;
const MAX_ZIP_ENTRIES = 10_000;

export class BundleArchive {
  private readonly zip: AdmZip;
  private readonly entriesByName: ReadonlyMap<string, AdmZip.IZipEntry>;
  readonly root: string;

  constructor(readonly archivePath: string) {
    // Reject symlinks, concurrent replacement, and oversized inputs before
    // passing bytes into the ZIP parser.
    this.zip = new AdmZip(readRegularFileSnapshot(archivePath, MAX_BUNDLE_ARCHIVE_BYTES));
    const entries = this.zip.getEntries();
    if (entries.length > MAX_ZIP_ENTRIES) {
      throw new Error(`Benchmark handoff has too many ZIP entries: ${entries.length}/${MAX_ZIP_ENTRIES}`);
    }
    this.entriesByName = validateZipEntryNames(entries);
    const matches = [...this.entriesByName.values()].filter(
      (entry) =>
        !entry.isDirectory &&
        (entry.entryName === HANDOFF_PATH || /^[A-Za-z0-9_.-]+\/handoff\/current-state\.json$/u.test(entry.entryName))
    );
    if (matches.length !== 1) {
      throw new Error(`Expected exactly one canonical ${HANDOFF_PATH}, found ${matches.length}`);
    }
    const entryName = matches[0]?.entryName ?? "";
    this.root = entryName.slice(0, -HANDOFF_PATH.length);
  }

  readBuffer(relativePath: string, maximumBytes = MAX_JSON_BYTES): Buffer {
    const entryName = this.entryName(relativePath);
    const entry = this.entriesByName.get(entryName);
    if (entry === undefined || entry.isDirectory) throw new Error(`Expected exactly one archive member ${entryName}`);
    if (entry.header.size > maximumBytes) {
      throw new Error(`Archive member exceeds ${maximumBytes} bytes: ${entryName}`);
    }
    const data = entry.getData();
    if (data.length > maximumBytes) throw new Error(`Archive member exceeds ${maximumBytes} bytes: ${entryName}`);
    return data;
  }

  readJson(relativePath: string): unknown {
    try {
      return parseStrictJsonBytes(this.readBuffer(relativePath));
    } catch (error) {
      throw new Error(`Invalid JSON in ${this.entryName(relativePath)}: ${(error as Error).message}`, { cause: error });
    }
  }

  async readNestedJson(
    relativeTarGzPath: string,
    selectedPaths: Record<string, string>
  ): Promise<Record<string, unknown>> {
    const compressed = this.readBuffer(relativeTarGzPath, MAX_NESTED_ARCHIVE_BYTES);
    for (const selectedPath of Object.values(selectedPaths)) assertCanonicalRelativePath(selectedPath);
    return extractSelectedJson(compressed, selectedPaths, relativeTarGzPath);
  }

  private entryName(relativePath: string): string {
    assertCanonicalRelativePath(relativePath);
    return this.root + relativePath;
  }
}

function validateZipEntryNames(entries: readonly AdmZip.IZipEntry[]): ReadonlyMap<string, AdmZip.IZipEntry> {
  const byName = new Map<string, AdmZip.IZipEntry>();
  const aliases = new Set<string>();
  for (const entry of entries) {
    const name = entry.entryName;
    const withoutDirectorySlash = entry.isDirectory && name.endsWith("/") ? name.slice(0, -1) : name;
    const segments = withoutDirectorySlash.split("/");
    const canonical = segments.join("/") + (entry.isDirectory ? "/" : "");
    if (
      withoutDirectorySlash.length === 0 ||
      name.includes("\\") ||
      name.includes("\0") ||
      [...name].some((character) => {
        const code = character.codePointAt(0)!;
        return code < 0x20 || code === 0x7f;
      }) ||
      name.startsWith("/") ||
      segments.some((segment) => segment === "" || segment === "." || segment === ".." || segment.includes(":")) ||
      canonical !== name
    ) {
      throw new Error(`Benchmark handoff contains a non-canonical ZIP member name: ${JSON.stringify(name)}`);
    }
    if (byName.has(name)) throw new Error(`Benchmark handoff contains duplicate ZIP member ${JSON.stringify(name)}`);
    if (aliases.has(withoutDirectorySlash)) {
      throw new Error(`Benchmark handoff contains aliased ZIP members at ${JSON.stringify(withoutDirectorySlash)}`);
    }
    byName.set(name, entry);
    aliases.add(withoutDirectorySlash);
  }
  return byName;
}

export function assertCanonicalRelativePath(value: string): void {
  if (
    !/^[A-Za-z0-9_.-]+(?:\/[A-Za-z0-9_.-]+)*$/u.test(value) ||
    value.split("/").some((segment) => segment === "." || segment === "..")
  ) {
    throw new Error(`Unsafe archive-relative path: ${value}`);
  }
}

async function extractSelectedJson(
  compressed: Buffer,
  selectedPaths: Record<string, string>,
  label: string
): Promise<Record<string, unknown>> {
  const output: Record<string, unknown> = {};
  const extract = tar.extract();
  const gunzip = createGunzip();

  return new Promise<Record<string, unknown>>((resolve, reject) => {
    let settled = false;
    let uncompressedBytes = 0;
    const fail = (error: Error) => {
      if (settled) return;
      settled = true;
      reject(error);
    };

    extract.on("entry", (header, stream, next) => {
      const match = Object.entries(selectedPaths).find(([, selectedPath]) => header.name === selectedPath);
      if (!match || header.type !== "file") {
        stream.resume();
        stream.on("end", next);
        stream.on("error", fail);
        return;
      }

      const [key] = match;
      const chunks: Buffer[] = [];
      let byteCount = 0;
      stream.on("data", (chunk: Buffer | string) => {
        const bytes = Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk);
        byteCount += bytes.length;
        if (byteCount > MAX_JSON_BYTES) {
          fail(new Error(`Nested JSON exceeds ${MAX_JSON_BYTES} bytes (${header.name}) in ${label}`));
          return;
        }
        chunks.push(bytes);
      });
      stream.on("error", fail);
      stream.on("end", () => {
        try {
          if (key in output) throw new Error(`Duplicate nested JSON match for ${key}`);
          output[key] = parseStrictJsonBytes(Buffer.concat(chunks));
          next();
        } catch (error) {
          fail(new Error(`Invalid nested JSON (${header.name}) in ${label}: ${(error as Error).message}`));
        }
      });
    });
    extract.on("finish", () => {
      if (settled) return;
      const missing = Object.keys(selectedPaths).filter((key) => !(key in output));
      if (missing.length > 0) {
        fail(new Error(`Nested archive ${label} is missing: ${missing.join(", ")}`));
        return;
      }
      settled = true;
      resolve(output);
    });
    extract.on("error", fail);
    gunzip.on("data", (chunk: Buffer) => {
      uncompressedBytes += chunk.length;
      if (uncompressedBytes > MAX_NESTED_UNCOMPRESSED_BYTES) {
        fail(new Error(`Nested archive exceeds ${MAX_NESTED_UNCOMPRESSED_BYTES} uncompressed bytes: ${label}`));
        gunzip.destroy();
        extract.destroy();
      }
    });
    gunzip.on("error", fail);
    Readable.from([compressed]).pipe(gunzip).pipe(extract);
  });
}
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import test from "node:test";

import AdmZip from "adm-zip";

import { BundleArchive, MAX_BUNDLE_ARCHIVE_BYTES } from "../src/benchmark-analysis/lib/archive.js";

const roots: string[] = [];

test.afterEach(() => {
  for (const root of roots.splice(0)) fs.rmSync(root, { recursive: true, force: true });
});

test("benchmark ZIP parsing rejects the CVE-2026-39244 forged allocation without expanding it", () => {
  const archivePath = temporaryPath("forged-size.zip");
  fs.writeFileSync(
    archivePath,
    craftForgedSizeZip("handoff/current-state.json", 3 * 1024 * 1024 * 1024, Buffer.from("A"))
  );

  const archive = new BundleArchive(archivePath);
  assert.throws(
    () => archive.readBuffer("handoff/current-state.json", Number.MAX_SAFE_INTEGER),
    /CRC32|invalid|entry|size/iu
  );
});

test("benchmark ZIP parsing rejects truncated and oversized compressed inputs", () => {
  assert.equal(MAX_BUNDLE_ARCHIVE_BYTES, 256 * 1024 * 1024);
  const valid = validBundle();
  const truncatedPath = temporaryPath("truncated.zip");
  fs.writeFileSync(truncatedPath, valid.subarray(0, valid.length - 10));
  assert.throws(() => new BundleArchive(truncatedPath));

  const oversizedPath = temporaryPath("oversized.zip");
  fs.writeFileSync(oversizedPath, Buffer.alloc(0));
  fs.truncateSync(oversizedPath, MAX_BUNDLE_ARCHIVE_BYTES + 1);
  assert.throws(() => new BundleArchive(oversizedPath), /exceeds|too large|maximum/iu);
});

test("benchmark ZIP parsing rejects duplicate and aliased central-directory names", () => {
  const duplicatePath = temporaryPath("duplicate.zip");
  fs.writeFileSync(duplicatePath, duplicateCentralDirectoryEntry(validBundle(), "handoff/current-state.json"));
  assert.throws(() => new BundleArchive(duplicatePath), /duplicate ZIP member/u);

  const aliased = new AdmZip();
  aliased.addFile("handoff/current-state.json", Buffer.from("{}\n"));
  aliased.addFile("x/handoff/current-state.json", Buffer.from("{}\n"));
  const aliasPath = temporaryPath("alias.zip");
  fs.writeFileSync(
    aliasPath,
    renameCentralDirectoryEntry(aliased.toBuffer(), "x/handoff/current-state.json", "./handoff/current-state.json")
  );
  assert.throws(() => new BundleArchive(aliasPath), /non-canonical ZIP member/u);
});

test("benchmark ZIP parsing applies selected-entry expansion budgets before extraction", () => {
  const zip = new AdmZip();
  zip.addFile("handoff/current-state.json", Buffer.alloc(2 * 1024 * 1024, 0x20));
  const archivePath = temporaryPath("ratio.zip");
  fs.writeFileSync(archivePath, zip.toBuffer());
  const archive = new BundleArchive(archivePath);
  assert.throws(() => archive.readBuffer("handoff/current-state.json", 1024), /exceeds 1024 bytes/u);
});

function temporaryPath(name: string): string {
  const root = fs.mkdtempSync(path.join(os.tmpdir(), "ultrafuzz-archive-security-"));
  roots.push(root);
  return path.join(root, name);
}

function validBundle(): Buffer {
  const zip = new AdmZip();
  zip.addFile("handoff/current-state.json", Buffer.from("{}\n"));
  return zip.toBuffer();
}

function craftForgedSizeZip(nameValue: string, declaredSize: number, content: Buffer): Buffer {
  const name = Buffer.from(nameValue);
  const local = Buffer.concat([
    u32(0x04034b50),
    u16(20),
    u16(0),
    u16(0),
    u16(0),
    u16(0),
    u32(0),
    u32(content.length),
    u32(declaredSize),
    u16(name.length),
    u16(0),
    name,
    content
  ]);
  const central = Buffer.concat([
    u32(0x02014b50),
    u16(20),
    u16(20),
    u16(0),
    u16(0),
    u16(0),
    u16(0),
    u32(0),
    u32(content.length),
    u32(declaredSize),
    u16(name.length),
    u16(0),
    u16(0),
    u16(0),
    u16(0),
    u32(0),
    u32(0),
    name
  ]);
  const end = Buffer.concat([
    u32(0x06054b50),
    u16(0),
    u16(0),
    u16(1),
    u16(1),
    u32(central.length),
    u32(local.length),
    u16(0)
  ]);
  return Buffer.concat([local, central, end]);
}

function u16(value: number): Buffer {
  const bytes = Buffer.alloc(2);
  bytes.writeUInt16LE(value >>> 0);
  return bytes;
}

function u32(value: number): Buffer {
  const bytes = Buffer.alloc(4);
  bytes.writeUInt32LE(value >>> 0);
  return bytes;
}

function duplicateCentralDirectoryEntry(zipBytes: Buffer, entryName: string): Buffer {
  const { centralOffset, centralSize, endOffset } = centralDirectory(zipBytes);
  let offset = centralOffset;
  let selected: Buffer | undefined;
  while (offset < centralOffset + centralSize) {
    assert.equal(zipBytes.readUInt32LE(offset), 0x02014b50);
    const nameLength = zipBytes.readUInt16LE(offset + 28);
    const extraLength = zipBytes.readUInt16LE(offset + 30);
    const commentLength = zipBytes.readUInt16LE(offset + 32);
    const recordLength = 46 + nameLength + extraLength + commentLength;
    const name = zipBytes.subarray(offset + 46, offset + 46 + nameLength).toString("utf8");
    if (name === entryName) selected = Buffer.from(zipBytes.subarray(offset, offset + recordLength));
    offset += recordLength;
  }
  assert.ok(selected);
  const end = Buffer.from(zipBytes.subarray(endOffset));
  end.writeUInt16LE(end.readUInt16LE(8) + 1, 8);
  end.writeUInt16LE(end.readUInt16LE(10) + 1, 10);
  end.writeUInt32LE(centralSize + selected.length, 12);
  return Buffer.concat([zipBytes.subarray(0, endOffset), selected, end]);
}

function renameCentralDirectoryEntry(zipBytes: Buffer, entryName: string, replacement: string): Buffer {
  assert.equal(Buffer.byteLength(entryName), Buffer.byteLength(replacement));
  const copy = Buffer.from(zipBytes);
  const { centralOffset, centralSize } = centralDirectory(copy);
  let offset = centralOffset;
  while (offset < centralOffset + centralSize) {
    assert.equal(copy.readUInt32LE(offset), 0x02014b50);
    const nameLength = copy.readUInt16LE(offset + 28);
    const extraLength = copy.readUInt16LE(offset + 30);
    const commentLength = copy.readUInt16LE(offset + 32);
    const nameStart = offset + 46;
    const name = copy.subarray(nameStart, nameStart + nameLength).toString("utf8");
    if (name === entryName) {
      copy.write(replacement, nameStart, nameLength, "utf8");
      return copy;
    }
    offset += 46 + nameLength + extraLength + commentLength;
  }
  assert.fail(`missing ZIP central-directory entry ${entryName}`);
}

function centralDirectory(zipBytes: Buffer): { centralOffset: number; centralSize: number; endOffset: number } {
  for (let offset = zipBytes.length - 22; offset >= Math.max(0, zipBytes.length - 65_557); offset -= 1) {
    if (zipBytes.readUInt32LE(offset) === 0x06054b50) {
      return {
        centralOffset: zipBytes.readUInt32LE(offset + 16),
        centralSize: zipBytes.readUInt32LE(offset + 12),
        endOffset: offset
      };
    }
  }
  throw new Error("ZIP end-of-central-directory record is missing");
}
